public class Main {
    static class Node {
        int val; Node next;
        Node(int v, Node n) { val = v; next = n; }
    }

    public static void main(String[] args) {
        System.out.println("start: 1 2 3 4 5, insert 0 at the front");
        // Array: every element moves one place right to free slot 0.
        int[] arr = new int[6];
        for (int i = 0; i < 5; i++) arr[i] = i + 1;
        int shifts = 0;
        for (int i = 5; i > 0; i--) { arr[i] = arr[i - 1]; shifts++; }
        arr[0] = 0;
        StringBuilder a = new StringBuilder();
        for (int x : arr) a.append(x).append(' ');
        System.out.println("array: " + a.toString().trim() + " (elements shifted: " + shifts + ")");

        // Linked list: a new node points to the old head. Nothing moves.
        Node head = null;
        for (int v = 5; v >= 1; v--) head = new Node(v, head);
        head = new Node(0, head);
        StringBuilder l = new StringBuilder();
        for (Node c = head; c != null; c = c.next) l.append(c.val).append(' ');
        System.out.println("list:  " + l.toString().trim() + " (elements shifted: 0)");

        // Reading index 3: the array jumps there, the list must hop node by node.
        Node cur = head;
        int hops = 0;
        while (hops < 3) { cur = cur.next; hops++; }
        System.out.println("array[3] = " + arr[3] + " after 0 hops");
        System.out.println("list get(3) = " + cur.val + " after " + hops + " hops");
        // Front insert: array O(N), list O(1). Read by index: array O(1), list O(N).
    }
}

