public class Main {
    static class Node {
        int val; Node prev, next;
        Node(int v) { val = v; }
    }

    static Node build(int[] a) {               // sets both next and prev
        Node head = new Node(a[0]), tail = head;
        for (int i = 1; i < a.length; i++) {
            Node n = new Node(a[i]);
            tail.next = n; n.prev = tail; tail = n;
        }
        return head;
    }

    static Node find(Node head, int v) {
        while (head.val != v) head = head.next;
        return head;
    }

    static String str(Node head) {
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(sb.length() > 0 ? " " : "").append(c.val);
        return sb.toString();
    }

    public static void main(String[] args) {
        int[] a = {10, 20, 30, 40, 50};
        System.out.println("list: 10 20 30 40 50, delete the node holding 40");

        // Singly linked (ignore prev): walk from the head to find the node before the target.
        Node head = build(a), target = find(head, 40);
        Node before = head;
        int hops = 0;
        while (before.next != target) { before = before.next; hops++; }
        before.next = target.next;
        System.out.println("singly: walked " + hops + " hops to find the node before it -> " + str(head));

        // Doubly linked: the target knows its neighbours, so two pointer writes finish the job.
        head = build(a); target = find(head, 40);
        target.prev.next = target.next;
        target.next.prev = target.prev;
        System.out.println("doubly: walked 0 hops (used prev) -> " + str(head));

        // prev also lets us read the list backwards from the tail.
        Node tail = head;
        while (tail.next != null) tail = tail.next;
        StringBuilder back = new StringBuilder();
        for (Node c = tail; c != null; c = c.prev) back.append(back.length() > 0 ? " " : "").append(c.val);
        System.out.println("doubly, read backwards: " + back);
        // Delete a held node: singly O(N) time, doubly O(1). Doubly costs one extra pointer per node.
    }
}

