using namespace std;

struct Node {
    int val; Node* prev = nullptr; Node* next = nullptr;
    Node(int v) : val(v) {}
};

Node* build(const vector<int>& a) {            // sets both next and prev
    Node* head = new Node(a[0]);
    Node* tail = head;
    for (size_t i = 1; i < a.size(); i++) {
        Node* n = new Node(a[i]);
        tail->next = n; n->prev = tail; tail = n;
    }
    return head;
}

Node* find(Node* head, int v) {
    while (head->val != v) head = head->next;
    return head;
}

string str(Node* head) {
    string s;
    for (Node* c = head; c; c = c->next) s += (s.empty() ? "" : " ") + to_string(c->val);
    return s;
}

int main() {
    vector<int> a = {10, 20, 30, 40, 50};
    cout << "list: 10 20 30 40 50, delete the node holding 40\n";

    // Singly linked (ignore prev): walk from the head to find the node before the target.
    Node* head = build(a);
    Node* target = find(head, 40);
    Node* before = head;
    int hops = 0;
    while (before->next != target) { before = before->next; hops++; }
    before->next = target->next;
    cout << "singly: walked " << hops << " hops to find the node before it -> " << str(head) << "\n";

    // Doubly linked: the target knows its neighbours, so two pointer writes finish the job.
    head = build(a); target = find(head, 40);
    target->prev->next = target->next;
    target->next->prev = target->prev;
    cout << "doubly: walked 0 hops (used prev) -> " << str(head) << "\n";

    // prev also lets us read the list backwards from the tail.
    Node* tail = head;
    while (tail->next) tail = tail->next;
