public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    static Node build(int[] a) {
        Node dummy = new Node(0), tail = dummy;   // the dummy also helps when building
        for (int x : a) { tail.next = new Node(x); tail = tail.next; }
        return dummy.next;
    }

    static String str(Node head) {
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(sb.length() > 0 ? " " : "").append(c.val);
        return sb.length() == 0 ? "(empty)" : sb.toString();
    }

    // Time O(N), extra space O(1).
    static Node removeAll(Node head, int target) {
        Node dummy = new Node(0);          // fake node placed before the real head
        dummy.next = head;
        Node prev = dummy;                 // prev is always the node BEFORE the one we check
        while (prev.next != null) {
            if (prev.next.val == target) prev.next = prev.next.next;  // unlink; works for the head too
            else prev = prev.next;
        }
        return dummy.next;                 // the real head may have changed
    }

    public static void main(String[] args) {
        int[][] tests = {{7, 7, 1, 7, 2}, {7, 7}, {1, 2}};
        for (int[] t : tests) {
            Node head = build(t);
            System.out.println("remove 7 from " + str(head) + " -> " + str(removeAll(head, 7)));
        }
    }
}

