using System;

class Node {
    public int val; public Node next;
    public Node(int v) { val = v; }
}

class Program {
    // Builds 1..n. If cycleTo > 0, the tail points back to the node holding cycleTo.
    static Node Build(int n, int cycleTo) {
        Node head = new Node(1), tail = head, target = null;
        for (int v = 2; v <= n; v++) { tail.next = new Node(v); tail = tail.next; }
        for (Node c = head; c != null; c = c.next) if (c.val == cycleTo) target = c;
        tail.next = target;
        return head;
    }

    // Time O(N), extra space O(1).
    static void Report(Node head) {
        Node slow = head, fast = head;
        bool found = false;
        while (fast != null && fast.next != null) {   // phase 1: slow 1 step, fast 2 steps
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) { found = true; break; }  // same node (not same value) = cycle
        }
        if (!found) { Console.WriteLine("cycle: no"); return; }
        Node p = head;                                // phase 2: one pointer back at the head,
        while (p != slow) { p = p.next; slow = slow.next; }   // both 1 step: they meet at the start
        int len = 1;
        for (Node c = p.next; c != p; c = c.next) len++;      // one lap counts the length
        Console.WriteLine("cycle: yes, starts at " + p.val + ", length " + len);
    }

    static void Main() {
        Console.WriteLine("list 1 2 3 4 5 6 with the tail pointing back to 3");
        Report(Build(6, 3));
        Console.WriteLine("list 1 2 3 with no cycle");
        Report(Build(3, 0));
    }
}

