    }

    static Node build(int[] a) {
        Node dummy = new Node(0), tail = dummy;
        for (int x : a) { tail.next = new Node(x); tail = tail.next; }
        return dummy.next;
    }

    static String str(Node head) {
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(sb.length() > 0 ? " " : "").append(c.val);
        return sb.length() == 0 ? "(empty)" : sb.toString();
    }

    // Iterative: O(N) time, O(1) extra space.
    static Node reverseIter(Node head) {
        Node prev = null, curr = head;     // prev = reversed part, curr = part not yet touched
        while (curr != null) {
            Node next = curr.next;         // save the rest before we break the link
            curr.next = prev;              // turn the arrow around
            prev = curr;
            curr = next;
        }
        return prev;                       // prev is the new head
    }

    // Recursive: O(N) time, O(N) stack frames.
    static Node reverseRec(Node head) {
        if (head == null || head.next == null) return head;
        Node newHead = reverseRec(head.next);   // reverse everything after head
        head.next.next = head;             // the node after head now points back to head
        head.next = null;                  // head becomes the tail; without this we get a cycle
        return newHead;
    }

