        return sb.length() == 0 ? "(empty)" : sb.toString();
    }

    // One pass: O(N) time, O(1) extra space. Assumes 1 <= n <= length.
    static Node removeNthFromEnd(Node head, int n) {
        Node dummy = new Node(0);
