public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    static Node build(int n) {             // builds 1 2 ... n
        Node dummy = new Node(0), tail = dummy;
        for (int v = 1; v <= n; v++) { tail.next = new Node(v); tail = tail.next; }
        return dummy.next;
    }

    static String str(Node head) {
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(sb.length() > 0 ? " " : "").append(c.val);
        return sb.toString();
    }

    // Both: O(N) time, O(1) extra space. The list must not be empty.
    static Node secondMiddle(Node head) {
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {   // fast may step off the end
            slow = slow.next;              // slow moves 1
            fast = fast.next.next;         // fast moves 2
        }
        return slow;                       // even length: the later of the two middles
    }

    static Node firstMiddle(Node head) {
        Node slow = head, fast = head;
        while (fast.next != null && fast.next.next != null) {  // stop one round earlier
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;                       // even length: the earlier of the two middles
    }

    public static void main(String[] args) {
        for (int n : new int[] {5, 6, 2, 1}) {
            Node head = build(n);
            System.out.println(str(head) + " -> second middle " + secondMiddle(head).val
                    + ", first middle " + firstMiddle(head).val);
        }
    }
}

