import java.util.HashMap;
import java.util.Map;

public class Main {
    static class Node {
        int key, val; Node prev, next;
        Node(int k, int v) { key = k; val = v; }
    }

    static int cap = 2;
    static Map<Integer, Node> map = new HashMap<>();          // key -> its node, O(1) lookup
    static Node head = new Node(0, 0), tail = new Node(0, 0);  // sentinels: head side = newest

    static void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }

    static void addFront(Node n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }

    // get and put: O(1) time each. Space O(capacity).
    static int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        unlink(n); addFront(n);            // a read makes the key the most recently used
        return n.val;
    }

    static int put(int key, int val) {     // returns the evicted key, or -1
        Node n = map.get(key);
        if (n != null) { n.val = val; unlink(n); addFront(n); return -1; }  // existing key: no eviction
        int evicted = -1;
        if (map.size() == cap) {
            Node old = tail.prev;          // least recently used sits next to the tail
            unlink(old);
            map.remove(old.key);           // the node stores its key for exactly this line
            evicted = old.key;
        }
        n = new Node(key, val);
        addFront(n); map.put(key, n);
        return evicted;
    }

    static void showPut(int k, int v) {
        int e = put(k, v);
        System.out.println("put(" + k + "," + v + ")" + (e >= 0 ? " evicts key " + e : ""));
    }

    public static void main(String[] args) {
        head.next = tail; tail.prev = head;
        System.out.println("capacity 2");
        showPut(1, 1); showPut(2, 2);
        System.out.println("get(1) = " + get(1));
        showPut(3, 3);
        System.out.println("get(2) = " + get(2));
        showPut(4, 4);
        System.out.println("get(1) = " + get(1) + ", get(3) = " + get(3) + ", get(4) = " + get(4));
    }
}

