  constructor(key, val) { this.key = key; this.val = val; this.prev = null; this.next = null; }
}

const cap = 2;
const map = new Map();                 // key -> its node, O(1) lookup
const head = new Node(0, 0), tail = new Node(0, 0);  // sentinels: head side = newest
head.next = tail; tail.prev = head;

function unlink(n) { n.prev.next = n.next; n.next.prev = n.prev; }

function addFront(n) {
  n.next = head.next; n.prev = head;
  head.next.prev = n; head.next = n;
}

// get and put: O(1) time each. Space O(capacity).
function get(key) {
  const n = map.get(key);
  if (n === undefined) return -1;
  unlink(n); addFront(n);              // a read makes the key the most recently used
  return n.val;
}

function put(key, val) {               // returns the evicted key, or -1
  let n = map.get(key);
  if (n !== undefined) { n.val = val; unlink(n); addFront(n); return -1; }  // existing key: no eviction
  let evicted = -1;
  if (map.size === cap) {
    const old = tail.prev;             // least recently used sits next to the tail
    unlink(old);
    map.delete(old.key);               // the node stores its key for exactly this line
    evicted = old.key;
  }
  n = new Node(key, val);
  addFront(n); map.set(key, n);
  return evicted;
}

function showPut(k, v) {
  const e = put(k, v);
  console.log("put(" + k + "," + v + ")" + (e >= 0 ? " evicts key " + e : ""));
}

console.log("capacity 2");
showPut(1, 1); showPut(2, 2);
console.log("get(1) = " + get(1));
showPut(3, 3);
console.log("get(2) = " + get(2));
showPut(4, 4);
console.log("get(1) = " + get(1) + ", get(3) = " + get(3) + ", get(4) = " + get(4));

