#include <bits/stdc++.h>
using namespace std;

struct Node {
    int key, val; Node* prev = nullptr; Node* next = nullptr;
    Node(int k, int v) : key(k), val(v) {}
};

int cap = 2;
unordered_map<int, Node*> table;       // key -> its node, O(1) lookup
Node* head = new Node(0, 0);           // sentinels: head side = newest
Node* tail = new Node(0, 0);

void unlink(Node* n) { n->prev->next = n->next; n->next->prev = n->prev; }

void addFront(Node* n) {
    n->next = head->next; n->prev = head;
    head->next->prev = n; head->next = n;
}

// get and put: O(1) time each. Space O(capacity).
int get(int key) {
    auto it = table.find(key);
    if (it == table.end()) return -1;
    unlink(it->second); addFront(it->second);   // a read makes the key the most recently used
    return it->second->val;
}

int put(int key, int val) {            // returns the evicted key, or -1
    auto it = table.find(key);
    if (it != table.end()) {           // existing key: no eviction
        it->second->val = val; unlink(it->second); addFront(it->second);
        return -1;
    }
    int evicted = -1;
    if ((int)table.size() == cap) {
        Node* old = tail->prev;        // least recently used sits next to the tail
        unlink(old);
        table.erase(old->key);         // the node stores its key for exactly this line
        evicted = old->key;
        delete old;
    }
    Node* n = new Node(key, val);
    addFront(n); table[key] = n;
    return evicted;
}

void showPut(int k, int v) {
    int e = put(k, v);
    cout << "put(" << k << "," << v << ")" << (e >= 0 ? " evicts key " + to_string(e) : "") << "\n";
}

int main() {
    head->next = tail; tail->prev = head;
    cout << "capacity 2\n";
    showPut(1, 1); showPut(2, 2);
    cout << "get(1) = " << get(1) << "\n";
    showPut(3, 3);
    cout << "get(2) = " << get(2) << "\n";
    showPut(4, 4);
    int a = get(1), b = get(3), c = get(4);
    cout << "get(1) = " << a << ", get(3) = " << b << ", get(4) = " << c << "\n";
    return 0;
}

