using System;
using System.Collections.Generic;

class Node {
    public int key, val; public Node prev, next;
    public Node(int k, int v) { key = k; val = v; }
}

class Program {
    static int cap = 2;
    static Dictionary<int, Node> map = new Dictionary<int, Node>();   // key -> its node, O(1) lookup
    static Node head = new Node(0, 0), tail = new Node(0, 0);         // sentinels: head side = newest

    static void Unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }

    static void AddFront(Node n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }

    // Get and Put: O(1) time each. Space O(capacity).
    static int Get(int key) {
        Node n;
        if (!map.TryGetValue(key, out n)) return -1;
        Unlink(n); AddFront(n);            // a read makes the key the most recently used
        return n.val;
    }

    static int Put(int key, int val) {     // returns the evicted key, or -1
        Node n;
        if (map.TryGetValue(key, out n)) { n.val = val; Unlink(n); AddFront(n); return -1; }  // existing key: no eviction
        int evicted = -1;
        if (map.Count == cap) {
            Node old = tail.prev;          // least recently used sits next to the tail
            Unlink(old);
            map.Remove(old.key);           // the node stores its key for exactly this line
            evicted = old.key;
        }
        n = new Node(key, val);
        AddFront(n); map[key] = n;
        return evicted;
    }

    static void ShowPut(int k, int v) {
        int e = Put(k, v);
        Console.WriteLine("put(" + k + "," + v + ")" + (e >= 0 ? " evicts key " + e : ""));
    }

    static void Main() {
        head.next = tail; tail.prev = head;
        Console.WriteLine("capacity 2");
        ShowPut(1, 1); ShowPut(2, 2);
        Console.WriteLine("get(1) = " + Get(1));
        ShowPut(3, 3);
        Console.WriteLine("get(2) = " + Get(2));
        ShowPut(4, 4);
        Console.WriteLine("get(1) = " + Get(1) + ", get(3) = " + Get(3) + ", get(4) = " + Get(4));
    }
}

