public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    static Node build(int n) {             // builds 1 2 ... n
        Node dummy = new Node(0), tail = dummy;
        for (int v = 1; v <= n; v++) { tail.next = new Node(v); tail = tail.next; }
        return dummy.next;
    }

    static String str(Node head) {
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(sb.length() > 0 ? " " : "").append(c.val);
        return sb.toString();
    }

    // O(N) time (each node is counted once and flipped once), O(1) extra space.
    static Node reverseKGroup(Node head, int k) {
        Node dummy = new Node(0);
        dummy.next = head;
        Node groupPrev = dummy;            // node just before the current group
        while (true) {
            Node kth = groupPrev;
            for (int i = 0; i < k && kth != null; i++) kth = kth.next;
            if (kth == null) break;        // fewer than k nodes left: leave them alone
            Node groupNext = kth.next;
            Node prev = groupNext, curr = groupPrev.next;   // start prev at the rest of the list
            while (curr != groupNext) {    // standard reversal, limited to this group
                Node next = curr.next;
                curr.next = prev;
                prev = curr;
                curr = next;
            }
            Node oldFirst = groupPrev.next;   // save BEFORE re-hooking; it is now the group's last node
            groupPrev.next = kth;
            groupPrev = oldFirst;
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        int[][] tests = {{8, 3}, {5, 2}, {2, 3}, {4, 4}};   // {length, k}
        for (int[] t : tests) {
            Node head = build(t[0]);
            System.out.println(str(head) + ", k = " + t[1] + " -> " + str(reverseKGroup(head, t[1])));
        }
    }
}

