    dummy.next = head;
    Node* groupPrev = &dummy;          // node just before the current group
    while (true) {
        Node* kth = groupPrev;
        for (int i = 0; i < k && kth; i++) kth = kth->next;
        if (!kth) break;               // fewer than k nodes left: leave them alone
        Node* groupNext = kth->next;
        Node* prev = groupNext;        // start prev at the rest of the list
        Node* curr = groupPrev->next;
        while (curr != groupNext) {    // standard reversal, limited to this group
            Node* next = curr->next;
            curr->next = prev;
            prev = curr;
            curr = next;
        }
        Node* oldFirst = groupPrev->next;   // save BEFORE re-hooking; it is now the group's last node
        groupPrev->next = kth;
        groupPrev = oldFirst;
    }
    return dummy.next;
}

int main() {
    vector<pair<int, int>> tests = {{8, 3}, {5, 2}, {2, 3}, {4, 4}};   // {length, k}
    for (auto& t : tests) {
        Node* head = build(t.first);
        string before = str(head);
        cout << before << ", k = " << t.second << " -> " << str(reverseKGroup(head, t.second)) << "\n";
    }
    return 0;
