import java.util.ArrayList;
import java.util.List;

public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    public static void main(String[] args) {
        int n = 1000;
        System.out.println("insert the values 0.." + (n - 1) + ", each one at the middle position (size / 2)");

        // Linked list: the splice is O(1), but first we must WALK to the position.
        Node dummy = new Node(-1);
        long hops = 0;
        for (int i = 0; i < n; i++) {
            Node prev = dummy;
            for (int s = 0; s < i / 2; s++) { prev = prev.next; hops++; }  // each hop may be a cache miss
            Node node = new Node(i);
            node.next = prev.next;
            prev.next = node;
        }

        // Array list: no walk, but the elements after the position move one place right.
        List<Integer> arr = new ArrayList<>();
        long shifts = 0;
        for (int i = 0; i < n; i++) {
            int pos = i / 2;
            shifts += arr.size() - pos;    // done as one fast block copy of neighbouring memory
            arr.add(pos, i);
        }

        // Both hold the same sequence.
        boolean same = true;
        Node c = dummy.next;
        for (int i = 0; i < n; i++) { if (c.val != arr.get(i)) same = false; c = c.next; }

        System.out.println("linked list: node hops to reach the position = " + hops);
        System.out.println("array list:  elements shifted               = " + shifts);
        System.out.println("same final contents: " + (same ? "yes" : "no"));
        System.out.println("first five: " + arr.get(0) + " " + arr.get(1) + " " + arr.get(2) + " " + arr.get(3) + " " + arr.get(4));
        // Both are O(N) per insert and O(N^2) in total. The array wins on constants, not on Big-O.
    }
}

