#include <bits/stdc++.h>
using namespace std;

struct Node {
    int val; Node* next = nullptr;
    Node(int v) : val(v) {}
};

Node* build(const vector<int>& a) {
    Node dummy(0);
    Node* tail = &dummy;
    for (int x : a) { tail->next = new Node(x); tail = tail->next; }
    return dummy.next;
}

string str(Node* head) {
    string s;
    for (Node* c = head; c; c = c->next) s += (s.empty() ? "" : " ") + to_string(c->val);
    return s.empty() ? "(empty)" : s;
}

Node* mergeTwo(Node* a, Node* b) {
    Node dummy(0);                     // dummy: no special case for the first node
    Node* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }
        else { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;            // attach whatever is left
    return dummy.next;
}

// N nodes in total, k lists: O(N log k) time, O(1) extra space.
Node* mergeK(vector<Node*>& lists) {
    int k = lists.size();
    if (k == 0) return nullptr;
    for (int step = 1; step < k; step *= 2)             // log k rounds
        for (int i = 0; i + step < k; i += 2 * step)    // merge neighbours: (0,1), (2,3), ...
            lists[i] = mergeTwo(lists[i], lists[i + step]);
    return lists[0];
}

int main() {
    vector<vector<int>> data = {{1, 4, 5}, {1, 3, 4}, {2, 6}, {}, {0, 9}};
    vector<Node*> lists;
    for (size_t i = 0; i < data.size(); i++) {
        lists.push_back(build(data[i]));
        cout << "list " << i << ": " << str(lists[i]) << "\n";
    }
    cout << "merged: " << str(mergeK(lists)) << "\n";
    return 0;
}

