using System;
using System.Collections.Generic;

class Node {
    public int val; public Node next;
    public Node(int v) { val = v; }
}

class Program {
    static Node Build(int[] a) {
        Node dummy = new Node(0), tail = dummy;
        foreach (int x in a) { tail.next = new Node(x); tail = tail.next; }
        return dummy.next;
    }

    static string Str(Node head) {
        List<int> o = new List<int>();
        for (Node c = head; c != null; c = c.next) o.Add(c.val);
        return o.Count == 0 ? "(empty)" : string.Join(" ", o);
    }

    static Node MergeTwo(Node a, Node b) {
        Node dummy = new Node(0), tail = dummy;   // dummy: no special case for the first node
        while (a != null && b != null) {
            if (a.val <= b.val) { tail.next = a; a = a.next; }
            else { tail.next = b; b = b.next; }
            tail = tail.next;
        }
        tail.next = (a != null) ? a : b;          // attach whatever is left
        return dummy.next;
    }

    // N nodes in total, k lists: O(N log k) time, O(1) extra space.
    static Node MergeK(Node[] lists) {
        int k = lists.Length;
        if (k == 0) return null;
        for (int step = 1; step < k; step *= 2)             // log k rounds
            for (int i = 0; i + step < k; i += 2 * step)    // merge neighbours: (0,1), (2,3), ...
                lists[i] = MergeTwo(lists[i], lists[i + step]);
        return lists[0];
    }

    static void Main() {
        int[][] data = { new int[] {1, 4, 5}, new int[] {1, 3, 4}, new int[] {2, 6}, new int[] {}, new int[] {0, 9} };
        Node[] lists = new Node[data.Length];
        for (int i = 0; i < data.Length; i++) {
            lists[i] = Build(data[i]);
            Console.WriteLine("list " + i + ": " + Str(lists[i]));
        }
        Console.WriteLine("merged: " + Str(MergeK(lists)));
    }
}

