public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    // Builds a list from the values and attaches `rest` (may be null) after its last node.
    static Node build(int[] a, Node rest) {
        Node dummy = new Node(0), tail = dummy;
        for (int x : a) { tail.next = new Node(x); tail = tail.next; }
        tail.next = rest;
        return dummy.next;
    }

    static String str(Node head) {
        StringBuilder sb = new StringBuilder();
        for (Node c = head; c != null; c = c.next) sb.append(sb.length() > 0 ? " " : "").append(c.val);
        return sb.toString();
    }

    // O(m + n) time, O(1) extra space. Returns the first shared node, or null.
    static Node intersection(Node headA, Node headB) {
        Node a = headA, b = headB;
        while (a != b) {                           // compares node identity, not values
            a = (a == null) ? headB : a.next;      // at the end, continue on the other list
            b = (b == null) ? headA : b.next;
        }
        return a;       // both have now walked lenA + lenB steps at most; null means no shared node
    }

    static void show(String name, Node x, Node y) {
        Node hit = intersection(x, y);
        System.out.println(name + ": " + (hit == null ? "no intersection" : "they meet at the node holding " + hit.val));
    }

    public static void main(String[] args) {
        Node shared = build(new int[] {8, 4, 5}, null);
        Node a = build(new int[] {4, 1}, shared);        // A and B end in the SAME three nodes
        Node b = build(new int[] {5, 6, 1}, shared);
        Node c = build(new int[] {1, 8, 4, 5}, null);    // C has equal values but its own nodes
        System.out.println("A: " + str(a));
        System.out.println("B: " + str(b));
        System.out.println("C: " + str(c));
        show("A and B", a, b);
        show("A and C", a, c);
    }
}

