import java.util.ArrayList;
import java.util.List;

public class Main {
    static final int SEGMENTS = 2, CAP = 2;        // 2 segments of 2 keys = 4 keys in total
    static List<List<Integer>> segs = new ArrayList<>();

    // Each segment is its own tiny LRU: oldest key at index 0, newest at the end.
    // A real cache gives every segment its own lock and an O(1) map + linked list;
    // a short list keeps this demo small. One access touches ONE segment only.
    static void access(int key) {
        int s = key % SEGMENTS;                    // choose the segment from the key
        List<Integer> seg = segs.get(s);
        if (seg.remove(Integer.valueOf(key))) {    // hit: move the key to the newest end
            seg.add(key);
            System.out.println("access " + key + " -> segment " + s + ": hit");
            return;
        }
        String msg = "access " + key + " -> segment " + s + ": miss";
        if (seg.size() == CAP) msg += ", evicts " + seg.remove(0);   // evict this segment's oldest key
        seg.add(key);
        System.out.println(msg);
    }

    public static void main(String[] args) {
        for (int i = 0; i < SEGMENTS; i++) segs.add(new ArrayList<>());
        int[] keys = {1, 2, 3, 1, 5, 7, 4};
        System.out.println("keys in order: 1 2 3 1 5 7 4 (segment = key % 2, 2 keys per segment)");
        for (int k : keys) access(k);
        for (int i = 0; i < SEGMENTS; i++) {
            StringBuilder sb = new StringBuilder();
            for (int k : segs.get(i)) sb.append(' ').append(k);
            System.out.println("segment " + i + " holds:" + sb);
        }
        // One global LRU of size 4 would end with 1 5 7 4: it would evict key 2 (the oldest overall).
        // The segmented cache evicted 3 and 1 and kept 2: eviction is only approximately LRU.
        // Time per access: O(1) with a map + list per segment (O(CAP) in this demo). Space O(total capacity).
    }
}

