#include <bits/stdc++.h>
using namespace std;

const int SEGMENTS = 2, CAP = 2;       // 2 segments of 2 keys = 4 keys in total
vector<vector<int>> segs(SEGMENTS);

// Each segment is its own tiny LRU: oldest key at index 0, newest at the end.
// A real cache gives every segment its own lock and an O(1) map + linked list;
// a short vector keeps this demo small. One access touches ONE segment only.
void access(int key) {
    int s = key % SEGMENTS;            // choose the segment from the key
    vector<int>& seg = segs[s];
    auto it = find(seg.begin(), seg.end(), key);
    if (it != seg.end()) {             // hit: move the key to the newest end
        seg.erase(it);
        seg.push_back(key);
        cout << "access " << key << " -> segment " << s << ": hit\n";
        return;
    }
    string msg = "access " + to_string(key) + " -> segment " + to_string(s) + ": miss";
    if ((int)seg.size() == CAP) {      // evict this segment's oldest key
        msg += ", evicts " + to_string(seg[0]);
        seg.erase(seg.begin());
    }
    seg.push_back(key);
    cout << msg << "\n";
}

int main() {
    vector<int> keys = {1, 2, 3, 1, 5, 7, 4};
    cout << "keys in order: 1 2 3 1 5 7 4 (segment = key % 2, 2 keys per segment)\n";
    for (int k : keys) access(k);
    for (int i = 0; i < SEGMENTS; i++) {
        cout << "segment " << i << " holds:";
        for (int k : segs[i]) cout << ' ' << k;
        cout << "\n";
    }
    // One global LRU of size 4 would end with 1 5 7 4: it would evict key 2 (the oldest overall).
    // The segmented cache evicted 3 and 1 and kept 2: eviction is only approximately LRU.
    // Time per access: O(1) with a map + list per segment (O(CAP) in this demo). Space O(total capacity).
    return 0;
}

