class Program {
    const int SEGMENTS = 2, CAP = 2;               // 2 segments of 2 keys = 4 keys in total
    static List<List<int>> segs = new List<List<int>>();

    // Each segment is its own tiny LRU: oldest key at index 0, newest at the end.
    // A real cache gives every segment its own lock and an O(1) map + linked list;
    // a short list keeps this demo small. One access touches ONE segment only.
    static void Access(int key) {
        int s = key % SEGMENTS;                    // choose the segment from the key
        List<int> seg = segs[s];
        if (seg.Remove(key)) {                     // hit: move the key to the newest end
            seg.Add(key);
            Console.WriteLine("access " + key + " -> segment " + s + ": hit");
            return;
        }
        string msg = "access " + key + " -> segment " + s + ": miss";
        if (seg.Count == CAP) {                    // evict this segment's oldest key
            msg += ", evicts " + seg[0];
            seg.RemoveAt(0);
        }
        seg.Add(key);
