public class Main {
    static class Node {
        int val; Node next;
        Node(int v) { val = v; }
    }

    static Node build(int n) {             // builds 1 2 ... n
        Node dummy = new Node(0), tail = dummy;
        for (int v = 1; v <= n; v++) { tail.next = new Node(v); tail = tail.next; }
        return dummy.next;
    }

    // Never loops forever, even on a broken list. O(N) time, O(1) extra space.
    static String safeStr(Node head) {
        if (head == null) return "(empty)";
        Node slow = head, fast = head;
        boolean cycle = false;
        while (fast != null && fast.next != null) {   // Floyd: slow 1 step, fast 2 steps
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) { cycle = true; break; }
        }
        Node start = null;
        if (cycle) {                       // find the first node of the cycle
            start = head;
            while (start != slow) { start = start.next; slow = slow.next; }
        }
        StringBuilder sb = new StringBuilder();
        int seenStart = 0;
        for (Node c = head; c != null; c = c.next) {
            if (c == start && ++seenStart == 2) break;    // second visit: stop printing
            sb.append(sb.length() > 0 ? " " : "").append(c.val);
        }
        return cycle ? sb + " -> CYCLE back to " + start.val : sb.toString();
    }

    public static void main(String[] args) {
        System.out.println("healthy list:       " + safeStr(build(4)));
        System.out.println("empty list:         " + safeStr(null));
        Node bad = build(5);               // simulate a pointer bug: the tail points back to node 3
        bad.next.next.next.next.next = bad.next.next;
        System.out.println("tail linked to 3:   " + safeStr(bad));
        Node self = build(1);              // one node pointing to itself
        self.next = self;
        System.out.println("node linked to itself: " + safeStr(self));
    }
}

