#include <bits/stdc++.h>
using namespace std;

struct Node {
    int val; Node* next = nullptr;
    Node(int v) : val(v) {}
};

Node* build(int n) {                   // builds 1 2 ... n
    Node dummy(0);
    Node* tail = &dummy;
    for (int v = 1; v <= n; v++) { tail->next = new Node(v); tail = tail->next; }
    return dummy.next;
}

// Never loops forever, even on a broken list. O(N) time, O(1) extra space.
string safeStr(Node* head) {
    if (!head) return "(empty)";
    Node* slow = head;
    Node* fast = head;
    bool cycle = false;
    while (fast && fast->next) {       // Floyd: slow 1 step, fast 2 steps
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) { cycle = true; break; }
    }
    Node* start = nullptr;
    if (cycle) {                       // find the first node of the cycle
        start = head;
        while (start != slow) { start = start->next; slow = slow->next; }
    }
    string s;
    int seenStart = 0;
    for (Node* c = head; c; c = c->next) {
        if (c == start && ++seenStart == 2) break;   // second visit: stop printing
        s += (s.empty() ? "" : " ") + to_string(c->val);
    }
    return cycle ? s + " -> CYCLE back to " + to_string(start->val) : s;
}

int main() {
    cout << "healthy list:       " << safeStr(build(4)) << "\n";
    cout << "empty list:         " << safeStr(nullptr) << "\n";
    Node* bad = build(5);              // simulate a pointer bug: the tail points back to node 3
    bad->next->next->next->next->next = bad->next->next;
    cout << "tail linked to 3:   " << safeStr(bad) << "\n";
    Node* self = build(1);             // one node pointing to itself
    self->next = self;
    cout << "node linked to itself: " << safeStr(self) << "\n";
    return 0;
}

