    // Never loops forever, even on a broken list. O(N) time, O(1) extra space.
    static string SafeStr(Node head) {
        if (head == null) return "(empty)";
        Node slow = head, fast = head;
        bool cycle = false;
        while (fast != null && fast.next != null) {   // Floyd: slow 1 step, fast 2 steps
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) { cycle = true; break; }
        }
        Node start = null;
        if (cycle) {                       // find the first node of the cycle
            start = head;
            while (start != slow) { start = start.next; slow = slow.next; }
        }
        List<int> o = new List<int>();
        int seenStart = 0;
        for (Node c = head; c != null; c = c.next) {
            if (c == start && ++seenStart == 2) break;    // second visit: stop printing
            o.Add(c.val);
        }
        string s = string.Join(" ", o);
        return cycle ? s + " -> CYCLE back to " + start.val : s;
    }

    static void Main() {
        Console.WriteLine("healthy list:       " + SafeStr(Build(4)));
        Console.WriteLine("empty list:         " + SafeStr(null));
        Node bad = Build(5);               // simulate a pointer bug: the tail points back to node 3
        bad.next.next.next.next.next = bad.next.next;
        Console.WriteLine("tail linked to 3:   " + SafeStr(bad));
        Node self = Build(1);              // one node pointing to itself
        self.next = self;
        Console.WriteLine("node linked to itself: " + SafeStr(self));
    }
}
